    this.isWord = false;
    /** @type {unknown} */
    this.value = undefined;
    /** @type {number} Number of stored words in this subtree, this node included. */
    this.count = 0;
  }
}

/**
 * Splits a string into an array of code points.
 * @param {string} s String to split.
 * @returns {number[]} Code points in order.
 */
function codePoints(s) {
  const out = [];
  for (const ch of s) out.push(ch.codePointAt(0));
  return out;
}

