    if (typeof word !== 'string') throw new TypeError('word must be a string');
    const cps = codePoints(word);
    let node = this.#root;
    for (const cp of cps) {
      let child = node.children.get(cp);
      if (!child) {
        child = new TrieNode();
        node.children.set(cp, child);
        this.#nodeCount += 1;
      }
      node = child;
    }
    let previous;
    if (node.isWord) {
      previous = node.value;
      node.value = value;
    } else {
      previous = undefined;
      node.isWord = true;
      node.value = value;
      this.#size += 1;
      // increment count along the path
      let cur = this.#root;
      cur.count += 1;
      for (const cp of cps) {
        cur = cur.children.get(cp);
        cur.count += 1;
      }
    }
    return previous;
  }

  /**
   * Walks to the node for a word, if it exists.
   * @param {string} word Word to walk to.
   * @returns {TrieNode | undefined} Node for that word, or undefined.
   */
